SELECT MAX(salary) AS second_highest
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

WITH ranked AS (
 SELECT e.*, DENSE_RANK() OVER (PARTITION BY department_id ORDER BY salary DESC) AS rnk
 FROM employees e
)
SELECT * FROM ranked WHERE rnk <= 3;
